<?php
declare(strict_types=1); require_once __DIR__.'/../shared/response.php'; require_once __DIR__.'/../shared/request.php'; require_once __DIR__.'/../shared/auth.php'; methodOnly('POST'); requireAdmin(); safeApi(function():void{$db=apiDatabase();$i=jsonRequest();$name=inputString($i,'name',true);$slug=inputString($i,'slug',true);$status=strtoupper((string)($i['status']??'ACTIVE'));if(!in_array($status,['ACTIVE','INACTIVE'],true))jsonResponse(false,'Invalid category status.',null,['status'=>'Use ACTIVE or INACTIVE.'],422);$s=$db->prepare('INSERT INTO categories(name,slug,image,status,sort_order) VALUES(:name,:slug,:image,:status,:sort_order)');$s->execute([':name'=>$name,':slug'=>$slug,':image'=>inputString($i,'image'),':status'=>$status,':sort_order'=>(int)($i['sort_order']??0)]);jsonResponse(true,'Category created successfully.',['id'=>(int)$db->lastInsertId()],[],201);});
